procedure PhysioChannelList {
  about "Remind our patients about their sessions"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  trigger every day at 08:00

  let all = fetch Sessions
  let due = filter all where status == "booked" and days_between(session_at, today()) == 2
  for each r in due up to 40 {
    let m = draft sms to r.mobile: "Hi {r.patient}, a reminder from the clinic: your session is in two days at {r.session_at}."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
    update r set status = "reminded"
  }
}

procedure PhysioChannelList {
  about "Aether cannot do this; list the sessions for the owner"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  trigger every day at 07:30

  let all = fetch Sessions
  let today = fetch Sessions where date_of(session_at) == today()
  for each r in today up to 40 {
