procedure CoffeeReorder {
  about "Reorder beans below their reorder point"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger every day at 06:30

  let all = fetch Beans
  let low = filter all where bags <= reorder_at
  for each r in low up to 2 {
    let cost = r.order_bags * r.price_per_bag
    if cost > $120.00 {
      notify owner "Reorder of {r.blend} would cost {cost}, over the $120 limit."
      skip
    }
    order "{r.order_bags} x {r.blend}" from r.roaster cost cost, ask owner first timeout 12 hours else skip
    log "ordered {r.blend}"
  }
}

