procedure HardwareRefunds {
  about "Handle returns within limits"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.opened {
    notify owner "Opened return {r.return_no} for {r.customer}. Please handle it."
    stop "opened returns go to owner"
  }
  if days_between(r.bought, today()) > 30 {
    notify owner "Old return {r.return_no} for {r.customer}. Please handle it."
    stop "old returns go to owner"
  }
  if r.amount > $100.00 {
    refund r.amount for r.return_no reason "return for the shop", ask owner first timeout 1 day else stop "big return not approved"
  }
  refund r.amount for r.return_no reason "return for the shop"
  let m = draft sms to r.phone: "Hi {r.customer}, your return of {r.amount} has been refunded."
  let ok = request approval of m from owner timeout 1 day else stop "refund not approved"
  send ok
  update r set status = "refunded"
}

procedure HardwareRefunds {
  about "Refund a return immediately"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.amount > $100.00 {
    notify owner "Refund of {r.amount} for return {r.return_no} would be over the $100 limit."
    stop "over the limit"
  }
  if r.amount <= $20.00 {
    refund r.amount for r.return_no reason "refund request"
  } else {
    refund r.amount for r.return_no reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
  }
  update r set status = "refunded"
}

