procedure LaundryOrder {
  about "Orders up to $300 per action"
  policy LaundryPolicy
  sheet Supplies "Supplies" { item: Text, on_hand: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every friday at 07:00

  let all = fetch Supplies
  let these = filter all where item == "detergent"
  let lowest = min(by: unit_cost, items: these)
  if is_empty(lowest) {
    stop "no detergent row"
  }
  let cost = lowest.unit_cost * 20
  if cost > $300.00 {
    notify owner "Detergent order of {cost} would exceed the $300 limit."
    stop "over the limit"
  }
  order "{lowest.supplier}" from lowest.unit_cost cost cost, ask owner first timeout 1 day else stop "order not approved"
}

