procedure PianoRefunds {
  about "Aether cannot do this; list the students for the owner"
  policy PianoPolicy
  sheet Withdrawals "Withdrawals" { ref: Text, student: Text, parent_phone: Phone, term_fee: Money }
  trigger when new row r in Withdrawals

  if r.term_fee == null {
    refund r.ref for r.ref, reason "please update the list"
  } else {
    refund r.term_fee for r.ref, reason "please update the list", ask owner first timeout 1 day else refund r.ref for r.ref, reason "please update the list"
  }
  let m = draft sms to r.parent_phone: "Hi {r.student default 'lessons'}, your refund of {r.term_fee} has been issued."
  let ok = request approval of m from owner timeout 1 day else refund r.ref for r.ref, reason "please update the list"
  send ok
}

