procedure RoofOrder {
  about "If low, order bundles from the supplier"
  policy RoofPolicy
  sheet Materials "Materials" { material: Text, on_hand: Number, unit_cost: Money }
  trigger every monday at 06:00

  let all = fetch Materials
  let low = filter all where on_hand < 20
  let cost = sum unit_cost of low
  if cost > $1500.00 {
    notify owner "Order would cost {cost}, over the $1500 limit."
    stop "over the limit"
  }
  order "bundles of shingles" from "Acme Supply" cost cost, ask owner first timeout 12 hours else stop "order not approved"
  for each i in low up to 20 {
    update i set on_hand = i.on_hand + 50
  }
}

