procedure FoodBankOrder {
  about "Orders cans of canned goods from Valley Wholesale"
  policy FoodBankPolicy
  sheet Prices "Prices" { item: Text, case_price: Money }
  trigger every monday at 10:00

  let all = fetch Prices
  let these = filter all where item == "cans of canned goods"
  let total = summarize sum case_price of these
  if total > $800.00 {
    notify owner "Over the limit! Total: {total}"
    stop "over the limit"
  }
  let order = order "cans of canned goods" from these cost $800.00, ask owner first timeout 1 day else stop "order not approved"
